def(
    "삼각비",
    "12",
    "사분원을 이용하여 삼각비의 값 구하기",
    SEC.값,
    "응용",
    (rng) => {
      const ang = intBetween(rng, 25, 65);
      const rad = ang * DEG;
      const s100 = Math.round(Math.sin(rad) * 100);
      const c100 = Math.round(Math.cos(rad) * 100);
      const t100 = Math.round(Math.tan(rad) * 100);
      const mode = intBetween(rng, 0, 4);
      const parts = [[s100], [c100], [t100], [s100, c100], [c100, t100]][mode]!;
      const x100 = parts.reduce((u, v) => u + v, 0);
      const asked = [
        `\\sin ${ang}^\\circ`,
        `\\cos ${ang}^\\circ`,
        `\\tan ${ang}^\\circ`,
        `\\sin ${ang}^\\circ+\\cos ${ang}^\\circ`,
        `\\cos ${ang}^\\circ+\\tan ${ang}^\\circ`,
      ][mode]!;
      const two = (v: number): string => (v / 100).toFixed(2);
      return {
        content: `반지름의 길이가 $1$인 사분원에서 $\\angle AOB=${ang}^\\circ$이다. 점 $B$에서 $\\overline{OA}$에 내린 수선의 발을 $H$라 하고, 점 $A$를 지나고 $\\overline{OA}$에 수직인 직선이 $\\overrightarrow{OB}$와 만나는 점을 $T$라 하자. $\\overline{BH}=${two(s100)}$, $\\overline{OH}=${two(c100)}$, $\\overline{AT}=${two(t100)}$일 때, $${asked}$의 값을 구하시오.`,
        answer: `$${two(x100)}$`,
        solution: `$\\overline{OB}=\\overline{OA}=1$이므로 $\\sin ${ang}^\\circ=\\dfrac{\\overline{BH}}{\\overline{OB}}=\\overline{BH}$, $\\cos ${ang}^\\circ=\\dfrac{\\overline{OH}}{\\overline{OB}}=\\overline{OH}$, $\\tan ${ang}^\\circ=\\dfrac{\\overline{AT}}{\\overline{OA}}=\\overline{AT}$이다.\n따라서 $${asked}=${two(x100)}$이다.`,
        facts: { ang, s100, c100, t100, mode, x100 },
        figureSpec: figQuadrant({ ang }),
      };
    },
  ),

actualSourceRule.quadrantHelperText:
function figQuadrant(opts: { ang: number }): FigureSpec {
  const t = Math.tan(opts.ang * DEG);
  const rad = t > 1.35 ? 62 : R_PX;
  const bx = rad * Math.cos(opts.ang * DEG);
  return {
    version: 2,
    points: {
      O: [CX, CY],
      A: { type: "on_circle", circle: "c", angle: 0 },
      Q: { type: "on_circle", circle: "c", angle: 90 },
      B: { type: "on_circle", circle: "c", angle: opts.ang },
      H: [r2(CX + bx), CY],
      T: [r2(CX + rad), r2(CY - rad * t)],
    },
    circles: { c: { center: "O", radius: rad, draw: false } },
    arcs: { q_AQ: { circle: "c", from: "A", to: "Q", dir: "ccw" } },
    segments: {
      OA: ["O", "A"],
      OQ: ["O", "Q"],
      OB: ["O", "B"],
      BT: ["B", "T"],
      BH: ["B", "H"],
      AT: ["A", "T"],
    },
    angles: {
      a_O: { vertex: "O", points: ["A", "B"], label: `${opts.ang}°` },
      r_H: { vertex: "H", points: ["B", "O"], right: true },
      r_A: { vertex: "A", points: ["O", "T"], right: true },
    },
    labels: { O: "O", A: "A", B: "B", H: "H", T: "T" },
  };
}
